static void fill_convex(Canvas *c, const float pts[][2], int n,
                        uint16_t colour) {
  float ymin = pts[0][1], ymax = ymin;
  for (int i = 1; i < n; i++) {
    ymin = fminf(ymin, pts[i][1]);
    ymax = fmaxf(ymax, pts[i][1]);
