  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(ymax));
  for (wide_t y = y0; y <= y1; y++) {
    const float sy = (float)y + 0.5f;
    float xl = INFINITY, xr = -INFINITY;
    for (int i = 0, j = n - 1; i < n; j = i++) {
      const float yi = pts[i][1], yj = pts[j][1];
